// Router v3 — nodo Code "Router" (runOnceForAllItems). Sustituye al Router v2 (21 KB).
// Responsabilidad UNICA: leer los argumentos y separar los tres ejes ANTES de tocar la zona:
//   1. de que tipo  -> p_types        (vocabulario de properties.property_type)
//   2. como es      -> p_features / p_condition / min_rooms / min_size / precios
//   3. donde        -> NO se decide aqui: se manda a resolve_zones (Postgres) lo que queda de la
//                      query tras quitar las facetas, mas municipality y address_contains.
// Sin diccionarios de municipios, sin ZONE_FIX, sin comodines: eso vive en zone_aliases y en
// catalog_zones (datos). "tres habitaciones" se consume como faceta ANTES de que ninguna zona
// pueda verlo; por eso 'tres' nunca vuelve a ser una calle.
const input = $json;
const str = v => (v == null ? '' : String(v)).trim();
const num = v => { const n = Number(v); return Number.isFinite(n) && n > 0 ? n : null; };
const normAccent = s => str(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const tokenize = s => normAccent(s).replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);

const idealistaId = str(input.idealista_id);
const addrContains = str(input.address_contains);
const query = str(input.query);
const municipality = str(input.municipality);
const matchCount = num(input.match_count) || 5;
const includeNonResidential = input.include_non_residential === true || input.include_non_residential === 'true';
let excludeIds = input.exclude_ids || [];
if (typeof excludeIds === 'string') { try { excludeIds = JSON.parse(excludeIds || '[]'); } catch (e) { excludeIds = []; } }
if (!Array.isArray(excludeIds)) excludeIds = [];
excludeIds = excludeIds.map(String).filter(Boolean);

// --- Vocabulario de facetas: EL MISMO que escribe Sync_catalogo_idealista (mapType/mapFeatures/
// mapCondition) y que lee match_pairs() para el matching semanal. Una entidad, un vocabulario.
const TYPE_WORDS = {
  piso: 'piso', pisos: 'piso', apartamento: 'piso', apartamentos: 'piso', estudio: 'piso', estudios: 'piso',
  atico: 'atico', aticos: 'atico', duplex: 'duplex',
  chalet: 'chalet', chalets: 'chalet', chale: 'chalet', adosado: 'chalet', adosados: 'chalet', adosada: 'chalet',
  pareado: 'chalet', pareados: 'chalet', unifamiliar: 'chalet', villa: 'chalet',
  local: 'local-oficina', locales: 'local-oficina', oficina: 'local-oficina', oficinas: 'local-oficina',
};
// 'casa', 'vivienda', 'inmueble', 'algo' = sin tipo (se consumen pero no filtran)
const TYPE_NEUTRAL = new Set(['casa', 'casas', 'vivienda', 'viviendas', 'inmueble', 'inmuebles', 'propiedad', 'propiedades', 'algo', 'nada']);
const FEATURE_WORDS = {
  piscina: 'piscina', piscinas: 'piscina',
  terraza: 'terraza', terrazas: 'terraza',
  jardin: 'jardin', jardines: 'jardin',
  trastero: 'trastero', trasteros: 'trastero',
  ascensor: 'ascensor',
  exterior: 'exterior',
  garaje: 'garaje', garajes: 'garaje', parking: 'garaje', aparcamiento: 'garaje', cochera: 'garaje',
  aire: 'aire', climatizacion: 'aire',
};
const CONDITION_PHRASES = [
  [/\b(a\s+reformar|para\s+reformar|reformar)\b/, 'a reformar'],
  [/\b(obra\s+nueva|nueva\s+construccion|a\s+estrenar)\b/, 'obra nueva'],
  [/\b(reformado|reformada|entrar\s+a\s+vivir|listo\s+para\s+entrar|lista\s+para\s+entrar)\b/, 'entrar a vivir'],
];
const NUM_WORDS = { un: 1, una: 1, uno: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10 };
const numFrom = w => (/^\d+$/.test(w) ? Number(w) : NUM_WORDS[w] || null);

// --- Parseo de facetas sobre la query (no sobre address_contains: eso ya es un lugar declarado).
let text = ' ' + normAccent(query).replace(/[^a-z0-9.,]+/g, ' ') + ' ';
const consume = re => { const m = text.match(re); if (m) text = text.replace(re, ' '); return m; };

let condition = null;
for (const [re, val] of CONDITION_PHRASES) { let hit = false; while (consume(re)) hit = true; if (hit && !condition) condition = val; }

let minRooms = num(input.min_rooms);
const mRooms = consume(/\b(\d+|un|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(habitaciones?|habs?|dormitorios?|cuartos?)\b/);
if (mRooms && !minRooms) minRooms = numFrom(mRooms[1]);
consume(/\b(\d+|un|una|dos|tres|cuatro|cinco|seis)\s+(banos?|aseos?)\b/); // no hay filtro de banos en la tool: se consume para que no parezca zona

let minSize = num(input.min_size);
const mSize = consume(/\b(\d{2,4})\s*(m2|metros(\s+cuadrados)?|m)\b/);
if (mSize && !minSize) minSize = Number(mSize[1]);

let maxPrice = num(input.max_price);
let minPrice = num(input.min_price);
// "300 mil", "1,2 millones", "menos de 400.000", "hasta 500k" — solo si el LLM no lo mando ya.
const mPrice = consume(/\b(menos\s+de|hasta|maximo|max|como\s+mucho|mas\s+de|desde|minimo|a\s+partir\s+de)?\s*(\d+(?:[.,]\d+)?)\s*(mil|millones|millon|k|m)?\s*(euros?|eur)?\b/);
if (mPrice && (mPrice[3] || mPrice[4] || /\d{5,}/.test(mPrice[2].replace(/[.,]/g, '')))) {
  let v = Number(mPrice[2].replace(/\.(?=\d{3}\b)/g, '').replace(',', '.'));
  const unit = mPrice[3] || '';
  if (unit === 'mil' || unit === 'k') v *= 1000; else if (unit.startsWith('millon') || unit === 'm') v *= 1000000;
  const q = mPrice[1] || '';
  if (/mas de|desde|minimo|a partir/.test(q)) { if (!minPrice) minPrice = v; } else if (!maxPrice) maxPrice = v;
}

const types = new Set();
const features = new Set();
const residueTokens = [];
for (const tok of tokenize(text)) {
  if (TYPE_WORDS[tok]) { types.add(TYPE_WORDS[tok]); continue; }
  if (TYPE_NEUTRAL.has(tok)) continue;
  if (FEATURE_WORDS[tok]) { features.add(FEATURE_WORDS[tok]); continue; }
  residueTokens.push(tok);
}
// "aire acondicionado" -> 'acondicionado' sobra; "plaza de garaje" -> 'plaza' sobra
const zoneText = residueTokens.filter(t => t !== 'acondicionado').join(' ').replace(/\bplaza de\b\s*$/, '').trim();

// --- Referencia directa
let derivedId = idealistaId;
if (!derivedId && /^\d{6,}$/.test(query)) derivedId = query;
const mUrl = query.match(/idealista\.com\/inmueble\/(\d+)/);
if (!derivedId && mUrl) derivedId = mUrl[1];

const userAskedNonResi = types.has('local-oficina') || /\b(local|garaje|trastero|terreno|parcela|nave)\b/.test(normAccent(query + ' ' + addrContains)) && !features.size;
const applyResiFilter = !includeNonResidential && !userAskedNonResi && !derivedId;

const hasAny = !!(derivedId || municipality || addrContains || zoneText || types.size || features.size || condition || minRooms || minSize || minPrice || maxPrice);
// browse = query generica ("algo", "lo que tengas", "casa") sin ningun criterio: vista amplia del catalogo
const path = derivedId ? 'byId' : (hasAny ? 'search' : (query ? 'browse' : 'empty'));

// Lo que resolve_zones (Postgres) tiene que mirar. marked=true: el LLM ya declaro que es un lugar.
const resolveInputs = [];
if (!derivedId) {
  if (municipality) resolveInputs.push({ src: 'municipality', text: municipality, marked: true });
  if (addrContains) resolveInputs.push({ src: 'address', text: addrContains, marked: true });
  if (zoneText)     resolveInputs.push({ src: 'query', text: zoneText, marked: false });
}

return [{ json: {
  path, derivedId: derivedId || null, applyResiFilter,
  query, municipality: municipality || null, address_contains: addrContains || null,
  max_price: maxPrice, min_price: minPrice, min_rooms: minRooms, min_size: minSize,
  match_count: matchCount, exclude_ids: excludeIds, include_non_residential: !applyResiFilter,
  facets: { types: [...types], features: [...features], condition },
  zone_text: zoneText,
  resolve_inputs: resolveInputs,
}}];

// Format For Agent v3 — nodo Code "Format For Agent" (runOnceForAllItems).
// Entrada: el objeto {results, total} de search_properties_json (siempre 1 item) + $('Plan').
// Salida: EXACTAMENTE el contrato que ya consumen Format For Voice (0eVx) y el AI Agent de
// WhatsApp: found, message, results[], catalogo_compacto[], zones[], match_quality,
// requested_terms, requested_location_text, unmatched_terms. Se anaden campos nuevos
// (zone_status, zone_candidates, conflict, tipo/extras por vivienda) sin quitar ninguno.
const EMPTY_EXTRA = { match_quality: 'none', requested_terms: [], requested_location_text: '', unmatched_terms: [], zone_status: 'none', zone_candidates: [], conflict: null };

let plan = {};
try { plan = $('Plan').first().json || {}; } catch (e) {}

if (plan.path === 'empty') {
  return [{ json: Object.assign({ found: 0, message: 'Necesito al menos un criterio (zona, presupuesto, características o referencia). ¿Qué buscas?', results: [], catalogo_compacto: [], zones: [] }, EMPTY_EXTRA) }];
}

const payload = $input.first().json || {};
const rows = Array.isArray(payload.results) ? payload.results : [];
const total = Number(payload.total) || rows.length;

const zoneStatus = plan.zone_status || 'none';
const requestedLocationText = (plan.requested_location_text || '').toString();
const zoneName = plan.zone ? plan.zone.name : '';
const requestedTerms = zoneName ? [zoneName] : (requestedLocationText ? [requestedLocationText] : []);

if (!rows.length) {
  return [{ json: Object.assign({ found: 0, message: 'No se encontraron viviendas que coincidan con esos criterios.', results: [], catalogo_compacto: [], zones: [] }, EMPTY_EXTRA,
    { requested_terms: requestedTerms, requested_location_text: requestedLocationText, unmatched_terms: requestedTerms, zone_status: zoneStatus, zone_candidates: plan.zone_candidates || [], conflict: plan.conflict || null }) }];
}

// partial = hay viviendas que cumplen el resto, pero NINGUNA en el sitio pedido:
//   - el RPC relajo la zona (match_level 'partial'), o
//   - el LLM declaro un sitio (address_contains) que no existe en la cartera ('unresolved').
const relaxed = rows[0].match_level === 'partial';
const matchQuality = (relaxed || zoneStatus === 'unresolved') ? 'partial' : 'exact';
const unmatchedTerms = matchQuality === 'partial' ? requestedTerms : [];

const formatted = rows.map(r => ({
  idealista_id: r.idealista_id,
  url: r.url,
  precio: r.price,
  direccion: r.address,
  municipio: r.municipality,
  distrito: r.district || null,
  barrio: r.neighborhood || null,
  calle: r.street || null,
  tipo: r.property_type || null,
  extras: r.features || [],
  estado: r.condition || null,
  habitaciones: r.rooms,
  banos: r.bathrooms,
  m2: r.size_m2,
  thumbnail: r.thumbnail_hosted || (r.idealista_id ? 'https://supabase-simarro.agentesia.madrid/storage/v1/object/public/thumbnails/' + r.idealista_id + '.jpg' : r.thumbnail),
  similitud: r.similarity != null ? Math.round(Number(r.similarity) * 100) / 100 : null,
  descripcion: (r.description_short || '').slice(0, 300),
  descripcion_corta: (r.description_short || '').slice(0, 100),
}));

const zoneCounts = {};
formatted.forEach(p => { const m = p.municipio || 'sin zona'; zoneCounts[m] = (zoneCounts[m] || 0) + 1; });
const zones = Object.entries(zoneCounts).map(([m, c]) => ({ municipio: m, count: c }));

const compacto = formatted.map(p => ({ id: p.idealista_id, zona: p.municipio, direccion: p.direccion, precio: p.precio, habs: p.habitaciones, m2: p.m2, banos: p.banos, tipo: p.tipo, desc: p.descripcion_corta }));

const summary = formatted.map((p, i) =>
  `${i + 1}. ${p.direccion || 'Dirección desconocida'} (${p.municipio || '?'}) — ${p.precio ? p.precio.toLocaleString('es-ES') + '€' : 'precio ?'} · ${p.habitaciones || '?'}h · ${p.m2 || '?'}m² · ID ${p.idealista_id}`
).join('\n');

return [{ json: {
  found: formatted.length, total_matching: total, message: summary, results: formatted, catalogo_compacto: compacto, zones,
  match_quality: matchQuality, requested_terms: requestedTerms, requested_location_text: requestedLocationText, unmatched_terms: unmatchedTerms,
  zone_status: zoneStatus, zone_candidates: plan.zone_candidates || [], conflict: plan.conflict || null,
  applied: { municipality: plan.municipality || null, zone: plan.zone || null, facets: plan.facets || {}, residue: plan.residue || '' },
} }];

const r = $('Format For Agent').first().json;
let ro={}; try{ ro=$('Plan').first().json||{}; }catch(e){}
if (ro.path === 'empty') return [{ json: r }];

// Clusters comerciales de Simarro, TODA la Comunidad de Madrid (18-ago-2026, decision Manu:
// "actualiza la lista con todo Madrid"). Base: las 9 comarcas oficiales de la Comunidad de
// Madrid (es.wikipedia.org/wiki/Anexo:Municipios_y_comarcas_de_la_Comunidad_de_Madrid,
// verificado 179/179 municipios); la comarca "Area Metropolitana y Corredor del Henares" se
// partio en 4 sub-zonas reales (noroeste/henares/sur/norte metropolitano) porque mezclaba
// puntas opuestas de Madrid (ej. Boadilla y Alcala de Henares) bajo una sola etiqueta, inutil
// para "cercania" real de comprador. Un cluster NUNCA se mezcla con otro, y ninguno incluye
// Madrid capital (mercado demasiado distinto/amplio para ser un 'cerca' util). Fuera de estos
// 12 clusters (resto de España, ej. Montuiri/Mallorca), sin cluster: solo coincidencia exacta,
// no se inventan vecinos que no existen en cartera.
// CORREGIDO 18-ago: Villaviciosa de Odón estaba mal en 'sierra' -- pertenece oficialmente al
// area metropolitana noroeste junto a Boadilla, no a la Cuenca del Guadarrama.
const CLUSTERS = [
  { name: 'sierra_norte', towns: ['la acebeda', 'alameda del valle', 'el atazar', 'berzosa del lozoya', 'el berrueco', 'braojos', 'buitrago del lozoya', 'bustarviejo', 'cabanillas de la sierra', 'la cabrera', 'canencia', 'cervera de buitrago', 'garganta de los montes', 'gargantilla del lozoya y pinilla de buitrago', 'gascones', 'la hiruela', 'horcajo de la sierra-aoslos', 'horcajuelo de la sierra', 'lozoya', 'lozoyuela-navas-sieteiglesias', 'madarcos', 'montejo de la sierra', 'navalafuente', 'navarredonda y san mames', 'patones', 'pinilla del valle', 'pinuecar-gandullas', 'pradena del rincon', 'puebla de la sierra', 'puentes viejas', 'rascafria', 'reduena', 'robledillo de la jara', 'robregordo', 'la serna del monte', 'somosierra', 'torrelaguna', 'torremocha de jarama', 'valdemanco', 'el vellon', 'venturada', 'villavieja del lozoya'] },
  { name: 'sierra_oeste', towns: ['aldea del fresno', 'cadalso de los vidrios', 'cenicientos', 'chapineria', 'colmenar del arroyo', 'fresnedillas de la oliva', 'navalagamella', 'navas del rey', 'pelayos de la presa', 'robledo de chavela', 'rozas de puerto real', 'san martin de valdeiglesias', 'santa maria de la alameda', 'valdemaqueda', 'villa del prado', 'villamanta', 'villamantilla', 'villanueva de perales', 'zarzalejo'] },
  { name: 'vegas', towns: ['ambite', 'aranjuez', 'belmonte de tajo', 'brea de tajo', 'carabana', 'chinchon', 'ciempozuelos', 'colmenar de oreja', 'estremera', 'fuentiduena de tajo', 'morata de tajuna', 'orusco de tajuna', 'perales de tajuna', 'san martin de la vega', 'tielmes', 'titulcia', 'valdaracete', 'valdelaguna', 'valdilecha', 'villaconejos', 'villamanrique de tajo', 'villar del olmo', 'villarejo de salvanes'] },
  { name: 'cuenca_guadarrama', towns: ['alpedrete', 'becerril de la sierra', 'el boalo', 'brunete', 'cercedilla', 'collado mediano', 'collado villalba', 'colmenarejo', 'el escorial', 'galapagar', 'guadarrama', 'los molinos', 'moralzarzal', 'navacerrada', 'quijorna', 'san lorenzo de el escorial', 'valdemorillo', 'villanueva de la canada', 'villanueva del pardillo'] },
  { name: 'cuenca_alta_manzanares', towns: ['colmenar viejo', 'guadalix de la sierra', 'hoyo de manzanares', 'manzanares el real', 'miraflores de la sierra', 'soto del real'] },
  { name: 'campina_henares', towns: ['anchuelo', 'campo real', 'corpa', 'loeches', 'nuevo baztan', 'olmeda de las fuentes', 'pezuela de las torres', 'pozuelo del rey', 'santorcaz', 'los santos de la humosa', 'torres de la alameda', 'valverde de alcala', 'villalbilla'] },
  { name: 'cuenca_media_jarama', towns: ['ajalvir', 'algete', 'camarma de esteruelas', 'cobena', 'daganzo de arriba', 'fresno de torote', 'fuente el saz de jarama', 'meco', 'el molar', 'paracuellos de jarama', 'pedrezuela', 'ribatejada', 'san agustin del guadalix', 'talamanca de jarama', 'valdeavero', 'valdeolmos-alalpardo', 'valdepielagos', 'valdetorres de jarama'] },
  { name: 'sur', towns: ['el alamo', 'arroyomolinos', 'batres', 'casarrubuelos', 'cubas de la sagra', 'grinon', 'humanes de madrid', 'moraleja de enmedio', 'navalcarnero', 'serranillos del valle', 'sevilla la nueva', 'torrejon de la calzada', 'torrejon de velasco', 'valdemoro'] },
  { name: 'noroeste_metropolitano', towns: ['boadilla del monte', 'majadahonda', 'las rozas de madrid', 'pozuelo de alarcon', 'torrelodones', 'villaviciosa de odon'] },
  { name: 'corredor_henares', towns: ['alcala de henares', 'coslada', 'san fernando de henares', 'torrejon de ardoz', 'mejorada del campo', 'velilla de san antonio', 'rivas-vaciamadrid', 'arganda del rey'] },
  { name: 'sur_metropolitano', towns: ['alcorcon', 'fuenlabrada', 'getafe', 'leganes', 'mostoles', 'parla', 'pinto'] },
  { name: 'norte_metropolitano', towns: ['alcobendas', 'san sebastian de los reyes', 'tres cantos'] },
];
const norm=s=>(s||'').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();

const asked=ro.address_contains||ro.municipality||null;
const askedNorm = norm(asked);
const cluster = asked ? CLUSTERS.find(c => c.towns.includes(askedNorm)) : null;
const clusterTowns = cluster ? new Set(cluster.towns) : null;
const anyClusterTown = new Set(CLUSTERS.flatMap(c => c.towns)); // fallback: busqueda generica sin zona

let cat=[]; try{ cat=$('Get Catálogo').all().map(i=>i.json).filter(x=>x&&!Array.isArray(x)&&x.municipality); }catch(e){ cat=[]; }
const maxP=ro.max_price||null,minP=ro.min_price||null,minR=ro.min_rooms||null,minS=ro.min_size||null,resi=!!ro.applyResiFilter;
const counts={};
for(const p of cat){ const m=p.municipality;
  if(asked&&norm(m)===askedNorm)continue;
  if(resi&&p.address&&/^(local|garaje|trastero|terreno|nave|parcela|edificio)\b/i.test(p.address))continue;
  if(maxP&&p.price!=null&&Number(p.price)>maxP)continue;
  if(minP&&p.price!=null&&Number(p.price)<minP)continue;
  if(minR&&p.rooms!=null&&Number(p.rooms)<minR)continue;
  if(minS&&p.size_m2!=null&&Number(p.size_m2)<minS)continue;
  if (asked) {
    if (!clusterTowns) continue; // la zona pedida no pertenece a ningun cluster conocido -> sin 'cerca'
    if (!clusterTowns.has(norm(m))) continue; // solo el MISMO cluster, nunca mezclar nucleo/sierra
  } else {
    if (!anyClusterTown.has(norm(m))) continue; // busqueda generica: cualquier zona comercial conocida
  }
  counts[m]=(counts[m]||0)+1; }
const zones=Object.entries(counts).map(([municipio,count])=>({municipio,count})).sort((a,b)=>b.count-a.count);
const zt=zones.map(z=>z.municipio).join(', ');

// Fuera de zona (18-ago, decision Manu): si lo pedido ni siquiera aparece en la cartera actual
// (ej. "Alcala de Henares", "Benidorm") -- ni coincidencia exacta ni cluster -- avisar de que
// Simarro no opera ahi, en vez del generico "no tengo con esos criterios, ¿ampliamos?" que da a
// entender que quizas SI haya algo si se insiste. Coincidencia por substring en ambos sentidos
// contra TODA la cartera activa (sin filtrar por precio/habitaciones: es presencia geografica,
// no disponibilidad concreta).
let message;
if (zones.length) {
  message = 'No hay nada en esa zona con esos criterios. Donde si hay viviendas que encajan ahora mismo, cerca: ' + zt + '.';
} else if (asked) {
  const enCartera = cat.some(p => { const m = norm(p.municipality); return askedNorm.includes(m) || m.includes(askedNorm); });
  message = enCartera
    ? r.message
    : 'No trabajamos en esa zona -- nuestra cartera está centrada en el noroeste de Madrid (Majadahonda, Las Rozas, Pozuelo, Boadilla del Monte y alrededores). ¿Buscas por esa zona o prefieres que te cuente qué tenemos disponible?';
} else {
  message = r.message;
}
return [{ json: { ...r, message, zones } }];

// Persiste en Kommo las preferencias de busqueda (zona/precio/habitaciones) que el AI Agent
// ya extrajo de la conversacion para esta llamada a Buscar_viviendas. Alimenta lead_preferences
// (via Reconcile lead_preferences) para que el matching semanal y match_pairs vean estos datos
// desde la primera busqueda, no solo si alguien los rellena a mano en Kommo despues.
//
// Solo WhatsApp pasa Lead_id (lo trae el webhook del chatbot) -> en voz shouldPatch sale
// siempre false y el siguiente IF va directo a Return busqueda sin tocar Kommo (en voz las
// preferencias las captura por su lado Captura_interes_llamadas_voz tras colgar).
// Nunca pisa con vacio: solo manda los campos que vienen rellenos esta vez.
//
// IMPORTANTE: este nodo SIEMPRE devuelve 1 item (nunca []). Un array vacio corta el flujo
// aqui mismo y Return busqueda no llegaria a ejecutarse (n8n no propaga con 0 items).
//
// Leemos del nodo Start explicitamente: a esta altura $json es lo que dejo Format For Agent
// (found/message/results), no los argumentos originales de la busqueda.
const start = $('Start').item.json;
const leadId = start.Lead_id;

const municipality = (start.municipality || '').toString().trim();
const maxPrice = Number(start.max_price) || null;
const minPrice = Number(start.min_price) || null;
const minRooms = Number(start.min_rooms) || null;

const cf = [];
if (municipality) cf.push({ field_id: 1373285, values: [{ value: municipality } ] });
if (maxPrice)     cf.push({ field_id: 1376040, values: [{ value: maxPrice } ] });
if (minPrice)     cf.push({ field_id: 1376044, values: [{ value: minPrice } ] });
// CF 1373289 (Habitaciones) es un select de Kommo con opciones fijas '1'..'4','5+'.
// Mandar un numero libre (p.ej. 2) hace que Kommo rechace el PATCH ENTERO -> se perdian
// tambien zona y precio, que si eran validos. Se normaliza a la opcion mas cercana.
let habOption = null;
if (minRooms) habOption = minRooms >= 5 ? '5+' : String(Math.max(1, Math.round(minRooms)));
if (habOption) cf.push({ field_id: 1373289, values: [{ value: habOption } ] });

const shouldPatch = Boolean(leadId) && cf.length > 0;

return [{ json: { shouldPatch, lead_id: leadId || null, custom_fields_values: cf } }];

// Plan v3 — nodo Code "Plan" (runOnceForAllItems), justo despues del HTTP "Resolve Zones"
// (POST /rest/v1/rpc/resolve_zones_json, body {"p_inputs": $json.resolve_inputs}).
// Recibe los CANDIDATOS de lugar que Postgres encontro en el texto y decide cuales aplicar:
//   - municipio (eje "donde", nivel 1) y una sub-zona (distrito/barrio/calle/provincia, nivel 2)
//   - conflicto municipio vs sub-zona: gana la mas especifica (bug 5-sep: "Las Rozas" + "Satelites")
//   - ambiguedad ('centro' existe en Madrid y en Villaviciosa): NO se aplica; se devuelve la lista
//     para que el agente pregunte, y el resto de la consulta sigue como descriptiva
//   - lo que el LLM declaro como lugar y no existe en la cartera -> 'unresolved' (=> partial)
// Salida: rpc_args para search_properties_json + flags para Format For Agent + los campos que
// Build Zones leia del Router (municipality, address_contains, max_price...).
const router = $('Router').first().json;
const cands = (($json && $json.candidates) || []).map(c => ({ ...c, score: Number(c.score) || 0 }));

const SPEC = { street: 5, neighborhood: 4, district: 3, municipality: 2, province: 1 };
const STOP = new Set(['en','de','del','la','el','los','las','un','una','unos','unas','al','y','o','con','sin','por','para','que','me','mi','es','esta','este','sobre','algo','nada','busco','quiero','hay','tiene','tengo','zona','barrio','calle','avenida','avda','paseo','plaza','camino','carretera','urbanizacion','urb','colonia','distrito','municipio','pueblo','cerca','junto','hacia','residencial','parque']);
const norm = s => (s == null ? '' : String(s)).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const rank = (a, b) => (b.exact - a.exact) || (b.tok_len - a.tok_len) || (b.score - a.score) || ((SPEC[b.kind] || 0) - (SPEC[a.kind] || 0));
const isMuniLevel = c => c.kind === 'municipality' || c.kind === 'province';
const coreLen = c => String(c.ngram || '').split(' ').filter(t => !STOP.has(t)).length; // palabras que de verdad se compararon

let muni = null;          // { name, kind:'municipality'|'province' }
let zone = null;          // { kind, name, municipality }
let zoneStatus = 'none';  // applied | unresolved | ambiguous | none
let conflict = null;
let zoneCandidates = [];
let requestedLocationText = '';
const consumed = new Set(); // posiciones de la query consumidas por zonas

const sameMuni = (c, m) => !m || !c.municipality || norm(c.municipality) === norm(m.name) || norm(c.municipality).startsWith(norm(m.name) + ' ');

// 1. municipality (el LLM lo declaro): puede venir un municipio, un ASR de municipio o, mal
//    usado, un distrito ("Los Satelites"). Se toma lo mejor; si es sub-zona, pasa a zone.
{
  const list = cands.filter(c => c.src === 'municipality').sort(rank);
  const best = list[0];
  if (best && isMuniLevel(best)) muni = { name: best.name, kind: best.kind };
  else if (best) { zone = { kind: best.kind, name: best.name, municipality: best.municipality }; zoneStatus = 'applied'; muni = best.municipality ? { name: best.municipality, kind: 'municipality' } : null; }
  else if (router.municipality) muni = { name: router.municipality, kind: 'raw' }; // prefijo en el RPC
}

// 2. address_contains (declarado como lugar): preferir lo que este dentro del municipio.
if (router.address_contains) {
  const list = cands.filter(c => c.src === 'address').sort(rank);
  const inside = list.filter(c => sameMuni(c, muni));
  const best = (inside.length ? inside : list)[0];
  if (!best) { zoneStatus = 'unresolved'; requestedLocationText = router.address_contains; }
  else if (isMuniLevel(best)) { if (!muni || muni.kind === 'raw') muni = { name: best.name, kind: best.kind }; else if (norm(best.name) !== norm(muni.name)) { conflict = `address ${best.name} vs municipality ${muni.name}`; muni = { name: best.name, kind: best.kind }; } }
  else {
    if (muni && !sameMuni(best, muni)) { conflict = `zone ${best.name} (${best.municipality}) vs municipality ${muni.name}`; muni = { name: best.municipality, kind: 'municipality' }; }
    zone = { kind: best.kind, name: best.name, municipality: best.municipality }; zoneStatus = 'applied';
    requestedLocationText = router.address_contains;
  }
}

// 3. query libre: greedy sobre spans no solapados, del mas largo/exacto al mas corto.
{
  const list = cands.filter(c => c.src === 'query').sort(rank);
  const taken = [];
  for (const c of list) {
    const overlaps = taken.some(t => c.tok_start < t.tok_start + t.tok_len && t.tok_start < c.tok_start + c.tok_len);
    if (overlaps) continue;
    // Fuzzy de UNA palabra (contando el core, como hace resolve_zones desde 002: 'urbanizacion
    // monte' o 'el cano' son una palabra) cuya frase continua con algo que no es lugar ni
    // stopword: era el principio de un nombre mas largo que NO existe ('urbanizacion Monte
    // Alegre' -> 'monte'). 'el cano' (next_tok null) o 'el centro de' (next_tok stopword) pasan.
    if (!c.exact && coreLen(c) <= 1 && c.next_tok && !STOP.has(c.next_tok)) {
      const nextCovered = taken.some(t => c.tok_start + 1 >= t.tok_start && c.tok_start + 1 < t.tok_start + t.tok_len);
      if (!nextCovered) continue;
    }
    if (isMuniLevel(c)) {
      if (!muni || muni.kind === 'raw') muni = { name: c.name, kind: c.kind };
      taken.push(c); continue;
    }
    if (zone) { taken.push(c); continue; } // ya hay sub-zona (la mas especifica/larga gano antes)
    // Todos los candidatos de este mismo span (cualquier certeza)
    const span = list.filter(o => o.tok_start === c.tok_start && o.tok_len === c.tok_len && !isMuniLevel(o)).sort(rank);
    const insideMuni = muni ? span.filter(o => sameMuni(o, muni)) : [];
    if (muni && insideMuni.length) {
      // dentro del municipio pedido gana aunque sea fuzzy: 'centro' + Las Rozas -> 'Rozas Centro'
      zone = { kind: insideMuni[0].kind, name: insideMuni[0].name, municipality: insideMuni[0].municipality }; zoneStatus = 'applied';
    } else {
      // sin municipio (o fuera de el): solo el grupo de maxima certeza cuenta para decidir
      const top = span.filter(o => o.exact === c.exact && Math.abs(o.score - c.score) < 1e-6);
      const munis = [...new Set(top.map(o => norm(o.municipality || o.name)))];
      if (munis.length > 1) {
        if (zoneStatus === 'none') { zoneStatus = 'ambiguous'; zoneCandidates = top.map(o => ({ kind: o.kind, name: o.name, municipality: o.municipality })); requestedLocationText = c.ngram; }
      } else {
        if (muni) conflict = `zone ${c.name} (${c.municipality}) vs municipality ${muni.name}`;
        zone = { kind: c.kind, name: c.name, municipality: c.municipality }; zoneStatus = 'applied';
        if (c.municipality) muni = { name: c.municipality, kind: 'municipality' };
      }
    }
    if (!requestedLocationText) requestedLocationText = c.ngram;
    taken.push(c);
  }
  for (const t of taken) for (let i = 0; i < t.tok_len; i++) consumed.add(t.tok_start + i);
}

// 3a. Ambiguedad ('centro' existe en Madrid y en Villaviciosa) con municipio conocido, venga del
// LLM o de la propia query en cualquier orden ('el centro de Majadahonda' resuelve 'centro' antes
// que 'majadahonda'): si un candidato esta en ese municipio, es ese; si ninguno lo esta, la zona
// pedida NO tiene stock ahi -> 'unresolved' (=> partial). Antes quedaba 'ambiguous' y Format lo
// etiquetaba 'exact' con viviendas de otra parte del municipio (el CRM las anclaba como la pedida).
if (zoneStatus === 'ambiguous' && muni) {
  const inside = zoneCandidates.filter(o => sameMuni(o, muni));
  zoneCandidates = [];
  if (inside.length) { zone = { kind: inside[0].kind, name: inside[0].name, municipality: inside[0].municipality }; zoneStatus = 'applied'; if (inside[0].municipality) muni = { name: inside[0].municipality, kind: 'municipality' }; }
  else zoneStatus = 'unresolved';
}

// 3b. El cliente nombro un sitio que NO existe en la cartera -> 'unresolved' (=> partial, texto
// honesto: 'En la chopera no me sale nada'). Es la causa comun de 'La Chopera' y 'zona norte de
// Madrid' marcados exact: el residuo de la query se trataba siempre como descriptor ('luminoso').
// Senales de que un token no resuelto es un LUGAR y no un descriptor:
//   (a) marcador fuerte delante: calle/urbanizacion/barrio/zona... ('urbanizacion Monte Alegre', 'zona norte')
//   (b) articulo delante: el/la/los/las                             ('La Chopera', 'en la sierra')
//   (c) nombre propio: el LLM lo escribio con mayuscula inicial     ('piso en Chopera'; no la 1a palabra)
// 'en'/'cerca'/'por' solos son demasiado genericos ('en buen estado', 'cerca de colegios').
if (!zone && zoneStatus !== 'ambiguous' && zoneStatus !== 'unresolved') {
  const qt = (router.zone_text || '').split(' ').filter(Boolean);
  const STRONG = new Set(['calle','avenida','avda','paseo','plaza','camino','carretera','urbanizacion','urb','barrio','colonia','residencial','zona']);
  const ART = new Set(['el','la','los','las']);
  const proper = new Set();
  String(router.query || '').split(/\s+/).filter(Boolean).forEach((w, k) => { if (k > 0 && /^[A-ZÁÉÍÓÚÑ][a-záéíóúñ]/.test(w)) proper.add(norm(w)); });
  const free = i => i < qt.length && !consumed.has(i) && !STOP.has(qt[i]) && !/^\d+$/.test(qt[i]);
  let start = -1, label = -1;
  for (let i = 0; i < qt.length && start < 0; i++) {
    if (!free(i)) continue;
    const prev = i > 0 ? qt[i - 1] : '';
    if (STRONG.has(prev) || ART.has(prev)) { start = i; label = i - 1; }
    else if (proper.has(qt[i])) { start = i; label = i; }
  }
  if (start >= 0) {
    let end = start; while (end < start + 4 && free(end)) end++;
    zoneStatus = 'unresolved'; requestedLocationText = qt.slice(label, end).join(' ');
    for (let i = start; i < end; i++) consumed.add(i);
  }
}

// 4. Residuo descriptivo = tokens de la query que no son facetas, ni zona, ni stopwords.
const qTokens = (router.zone_text || '').split(' ').filter(Boolean);
const residue = qTokens.filter((t, i) => !consumed.has(i) && !STOP.has(t) && !/^\d+$/.test(t));
const USE_EMBEDDING = true; // fase 1b: ranking semantico solo cuando queda residuo descriptivo
const needsEmbedding = USE_EMBEDDING && (router.path === 'search' || router.path === 'browse') && residue.length > 0;

const f = router.facets || {};
// Una provincia ("Mallorca" -> Balears) no es municipio: viaja como zona de nivel provincia.
if (muni && muni.kind === 'province') { if (!zone) zone = { kind: 'province', name: muni.name, municipality: null }; if (zoneStatus === 'none') zoneStatus = 'applied'; muni = null; }
const rpcArgs = {
  p_idealista_id: router.derivedId || null,
  p_municipality: muni ? muni.name : null,
  p_zone_kind: zone ? zone.kind : null,
  p_zone_name: zone ? zone.name : null,
  p_types: (f.types && f.types.length) ? f.types : null,
  p_features: (f.features && f.features.length) ? f.features : null,
  p_condition: f.condition || null,
  p_min_rooms: router.min_rooms || null,
  p_min_size: router.min_size || null,
  p_min_price: router.min_price || null,
  p_max_price: router.max_price || null,
  p_include_non_residential: !router.applyResiFilter,
  p_exclude_ids: router.exclude_ids || [],
  p_limit: router.path === 'byId' ? 1 : Math.max(router.match_count || 5, (router.path === 'browse' || (!muni && !zone && !f.types?.length && !f.features?.length && !router.min_rooms && !router.max_price && !router.min_price && !router.min_size)) ? 25 : 0),
};

return [{ json: {
  // compat Build Zones / Preparar CF (leian estos nombres del Router)
  path: router.path, applyResiFilter: router.applyResiFilter, query: router.query,
  municipality: muni ? muni.name : null, address_contains: zone ? zone.name : (router.address_contains || null),
  max_price: router.max_price, min_price: router.min_price, min_rooms: router.min_rooms, min_size: router.min_size,
  match_count: router.match_count, exclude_ids: router.exclude_ids,
  // decision
  rpc_args: rpcArgs,
  zone_status: zoneStatus, zone, muni, conflict, zone_candidates: zoneCandidates,
  requested_location_text: requestedLocationText,
  facets: f, residue: residue.join(' '), needs_embedding: needsEmbedding,
}}];

// Router v3 — nodo Code "Router" (runOnceForAllItems). Sustituye al Router v2 (21 KB).
// Responsabilidad UNICA: leer los argumentos y separar los tres ejes ANTES de tocar la zona:
//   1. de que tipo  -> p_types        (vocabulario de properties.property_type)
//   2. como es      -> p_features / p_condition / min_rooms / min_size / precios
//   3. donde        -> NO se decide aqui: se manda a resolve_zones (Postgres) lo que queda de la
//                      query tras quitar las facetas, mas municipality y address_contains.
// Sin diccionarios de municipios, sin ZONE_FIX, sin comodines: eso vive en zone_aliases y en
// catalog_zones (datos). "tres habitaciones" se consume como faceta ANTES de que ninguna zona
// pueda verlo; por eso 'tres' nunca vuelve a ser una calle.
const input = $json;
const str = v => (v == null ? '' : String(v)).trim();
const num = v => { const n = Number(v); return Number.isFinite(n) && n > 0 ? n : null; };
const normAccent = s => str(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const tokenize = s => normAccent(s).replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);

const idealistaId = str(input.idealista_id);
const addrContains = str(input.address_contains);
const query = str(input.query);
const municipality = str(input.municipality);
const matchCount = num(input.match_count) || 5;
const includeNonResidential = input.include_non_residential === true || input.include_non_residential === 'true';
let excludeIds = input.exclude_ids || [];
if (typeof excludeIds === 'string') { try { excludeIds = JSON.parse(excludeIds || '[]'); } catch (e) { excludeIds = []; } }
if (!Array.isArray(excludeIds)) excludeIds = [];
excludeIds = excludeIds.map(String).filter(Boolean);

// --- Vocabulario de facetas: EL MISMO que escribe Sync_catalogo_idealista (mapType/mapFeatures/
// mapCondition) y que lee match_pairs() para el matching semanal. Una entidad, un vocabulario.
const TYPE_WORDS = {
  piso: 'piso', pisos: 'piso', apartamento: 'piso', apartamentos: 'piso', estudio: 'piso', estudios: 'piso',
  atico: 'atico', aticos: 'atico', duplex: 'duplex',
  chalet: 'chalet', chalets: 'chalet', chale: 'chalet', adosado: 'chalet', adosados: 'chalet', adosada: 'chalet',
  pareado: 'chalet', pareados: 'chalet', unifamiliar: 'chalet', villa: 'chalet',
  local: 'local-oficina', locales: 'local-oficina', oficina: 'local-oficina', oficinas: 'local-oficina',
};
// 'casa', 'vivienda', 'inmueble', 'algo' = sin tipo (se consumen pero no filtran)
const TYPE_NEUTRAL = new Set(['casa', 'casas', 'vivienda', 'viviendas', 'inmueble', 'inmuebles', 'propiedad', 'propiedades', 'algo', 'nada']);
const FEATURE_WORDS = {
  piscina: 'piscina', piscinas: 'piscina',
  terraza: 'terraza', terrazas: 'terraza',
  jardin: 'jardin', jardines: 'jardin',
  trastero: 'trastero', trasteros: 'trastero',
  ascensor: 'ascensor',
  exterior: 'exterior',
  garaje: 'garaje', garajes: 'garaje', parking: 'garaje', aparcamiento: 'garaje', cochera: 'garaje',
  aire: 'aire', climatizacion: 'aire',
};
const CONDITION_PHRASES = [
  [/\b(a\s+reformar|para\s+reformar|reformar)\b/, 'a reformar'],
  [/\b(obra\s+nueva|nueva\s+construccion|a\s+estrenar)\b/, 'obra nueva'],
  [/\b(reformado|reformada|entrar\s+a\s+vivir|listo\s+para\s+entrar|lista\s+para\s+entrar)\b/, 'entrar a vivir'],
];
const NUM_WORDS = { un: 1, una: 1, uno: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10 };
const numFrom = w => (/^\d+$/.test(w) ? Number(w) : NUM_WORDS[w] || null);

// --- Parseo de facetas sobre la query (no sobre address_contains: eso ya es un lugar declarado).
let text = ' ' + normAccent(query).replace(/[^a-z0-9.,]+/g, ' ') + ' ';
const consume = re => { const m = text.match(re); if (m) text = text.replace(re, ' '); return m; };

let condition = null;
for (const [re, val] of CONDITION_PHRASES) { let hit = false; while (consume(re)) hit = true; if (hit && !condition) condition = val; }

let minRooms = num(input.min_rooms);
const mRooms = consume(/\b(\d+|un|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(habitaciones?|habs?|dormitorios?|cuartos?)\b/);
if (mRooms && !minRooms) minRooms = numFrom(mRooms[1]);
consume(/\b(\d+|un|una|dos|tres|cuatro|cinco|seis)\s+(banos?|aseos?)\b/); // no hay filtro de banos en la tool: se consume para que no parezca zona

let minSize = num(input.min_size);
const mSize = consume(/\b(\d{2,4})\s*(m2|metros(\s+cuadrados)?|m)\b/);
if (mSize && !minSize) minSize = Number(mSize[1]);

let maxPrice = num(input.max_price);
let minPrice = num(input.min_price);
// "300 mil", "1,2 millones", "menos de 400.000", "hasta 500k" — solo si el LLM no lo mando ya.
const mPrice = consume(/\b(menos\s+de|hasta|maximo|max|como\s+mucho|mas\s+de|desde|minimo|a\s+partir\s+de)?\s*(\d+(?:[.,]\d+)?)\s*(mil|millones|millon|k|m)?\s*(euros?|eur)?\b/);
if (mPrice && (mPrice[3] || mPrice[4] || /\d{5,}/.test(mPrice[2].replace(/[.,]/g, '')))) {
  let v = Number(mPrice[2].replace(/\.(?=\d{3}\b)/g, '').replace(',', '.'));
  const unit = mPrice[3] || '';
  if (unit === 'mil' || unit === 'k') v *= 1000; else if (unit.startsWith('millon') || unit === 'm') v *= 1000000;
  const q = mPrice[1] || '';
  if (/mas de|desde|minimo|a partir/.test(q)) { if (!minPrice) minPrice = v; } else if (!maxPrice) maxPrice = v;
}

const types = new Set();
const features = new Set();
const residueTokens = [];
for (const tok of tokenize(text)) {
  if (TYPE_WORDS[tok]) { types.add(TYPE_WORDS[tok]); continue; }
  if (TYPE_NEUTRAL.has(tok)) continue;
  if (FEATURE_WORDS[tok]) { features.add(FEATURE_WORDS[tok]); continue; }
  residueTokens.push(tok);
}
// "aire acondicionado" -> 'acondicionado' sobra; "plaza de garaje" -> 'plaza' sobra
const zoneText = residueTokens.filter(t => t !== 'acondicionado').join(' ').replace(/\bplaza de\b\s*$/, '').trim();

// --- Referencia directa
let derivedId = idealistaId;
if (!derivedId && /^\d{6,}$/.test(query)) derivedId = query;
const mUrl = query.match(/idealista\.com\/inmueble\/(\d+)/);
if (!derivedId && mUrl) derivedId = mUrl[1];

const userAskedNonResi = types.has('local-oficina') || /\b(local|garaje|trastero|terreno|parcela|nave)\b/.test(normAccent(query + ' ' + addrContains)) && !features.size;
const applyResiFilter = !includeNonResidential && !userAskedNonResi && !derivedId;

const hasAny = !!(derivedId || municipality || addrContains || zoneText || types.size || features.size || condition || minRooms || minSize || minPrice || maxPrice);
// browse = query generica ("algo", "lo que tengas", "casa") sin ningun criterio: vista amplia del catalogo
const path = derivedId ? 'byId' : (hasAny ? 'search' : (query ? 'browse' : 'empty'));

// Lo que resolve_zones (Postgres) tiene que mirar. marked=true: el LLM ya declaro que es un lugar.
const resolveInputs = [];
if (!derivedId) {
  if (municipality) resolveInputs.push({ src: 'municipality', text: municipality, marked: true });
  if (addrContains) resolveInputs.push({ src: 'address', text: addrContains, marked: true });
  if (zoneText)     resolveInputs.push({ src: 'query', text: zoneText, marked: false });
}

return [{ json: {
  path, derivedId: derivedId || null, applyResiFilter,
  query, municipality: municipality || null, address_contains: addrContains || null,
  max_price: maxPrice, min_price: minPrice, min_rooms: minRooms, min_size: minSize,
  match_count: matchCount, exclude_ids: excludeIds, include_non_residential: !applyResiFilter,
  facets: { types: [...types], features: [...features], condition },
  zone_text: zoneText,
  resolve_inputs: resolveInputs,
}}];

// Format For Agent v3 — nodo Code "Format For Agent" (runOnceForAllItems).
// Entrada: el objeto {results, total} de search_properties_json (siempre 1 item) + $('Plan').
// Salida: EXACTAMENTE el contrato que ya consumen Format For Voice (0eVx) y el AI Agent de
// WhatsApp: found, message, results[], catalogo_compacto[], zones[], match_quality,
// requested_terms, requested_location_text, unmatched_terms. Se anaden campos nuevos
// (zone_status, zone_candidates, conflict, tipo/extras por vivienda) sin quitar ninguno.
const EMPTY_EXTRA = { match_quality: 'none', requested_terms: [], requested_location_text: '', unmatched_terms: [], zone_status: 'none', zone_candidates: [], conflict: null };

let plan = {};
try { plan = $('Plan').first().json || {}; } catch (e) {}

if (plan.path === 'empty') {
  return [{ json: Object.assign({ found: 0, message: 'Necesito al menos un criterio (zona, presupuesto, características o referencia). ¿Qué buscas?', results: [], catalogo_compacto: [], zones: [] }, EMPTY_EXTRA) }];
}

const payload = $input.first().json || {};
const rows = Array.isArray(payload.results) ? payload.results : [];
const total = Number(payload.total) || rows.length;

const zoneStatus = plan.zone_status || 'none';
const requestedLocationText = (plan.requested_location_text || '').toString();
const zoneName = plan.zone ? plan.zone.name : '';
const requestedTerms = zoneName ? [zoneName] : (requestedLocationText ? [requestedLocationText] : []);

if (!rows.length) {
  return [{ json: Object.assign({ found: 0, message: 'No se encontraron viviendas que coincidan con esos criterios.', results: [], catalogo_compacto: [], zones: [] }, EMPTY_EXTRA,
    { requested_terms: requestedTerms, requested_location_text: requestedLocationText, unmatched_terms: requestedTerms, zone_status: zoneStatus, zone_candidates: plan.zone_candidates || [], conflict: plan.conflict || null }) }];
}

// partial = hay viviendas que cumplen el resto, pero NINGUNA en el sitio pedido:
//   - el RPC relajo la zona (match_level 'partial'), o
//   - el LLM declaro un sitio (address_contains) que no existe en la cartera ('unresolved').
const relaxed = rows[0].match_level === 'partial';
const matchQuality = (relaxed || zoneStatus === 'unresolved') ? 'partial' : 'exact';
const unmatchedTerms = matchQuality === 'partial' ? requestedTerms : [];

const formatted = rows.map(r => ({
  idealista_id: r.idealista_id,
  url: r.url,
  precio: r.price,
  direccion: r.address,
  municipio: r.municipality,
  distrito: r.district || null,
  barrio: r.neighborhood || null,
  calle: r.street || null,
  tipo: r.property_type || null,
  extras: r.features || [],
  estado: r.condition || null,
  habitaciones: r.rooms,
  banos: r.bathrooms,
  m2: r.size_m2,
  thumbnail: r.thumbnail_hosted || (r.idealista_id ? 'https://supabase-simarro.agentesia.madrid/storage/v1/object/public/thumbnails/' + r.idealista_id + '.jpg' : r.thumbnail),
  similitud: r.similarity != null ? Math.round(Number(r.similarity) * 100) / 100 : null,
  descripcion: (r.description_short || '').slice(0, 300),
  descripcion_corta: (r.description_short || '').slice(0, 100),
}));

const zoneCounts = {};
formatted.forEach(p => { const m = p.municipio || 'sin zona'; zoneCounts[m] = (zoneCounts[m] || 0) + 1; });
const zones = Object.entries(zoneCounts).map(([m, c]) => ({ municipio: m, count: c }));

const compacto = formatted.map(p => ({ id: p.idealista_id, zona: p.municipio, direccion: p.direccion, precio: p.precio, habs: p.habitaciones, m2: p.m2, banos: p.banos, tipo: p.tipo, desc: p.descripcion_corta }));

const summary = formatted.map((p, i) =>
  `${i + 1}. ${p.direccion || 'Dirección desconocida'} (${p.municipio || '?'}) — ${p.precio ? p.precio.toLocaleString('es-ES') + '€' : 'precio ?'} · ${p.habitaciones || '?'}h · ${p.m2 || '?'}m² · ID ${p.idealista_id}`
).join('\n');

return [{ json: {
  found: formatted.length, total_matching: total, message: summary, results: formatted, catalogo_compacto: compacto, zones,
  match_quality: matchQuality, requested_terms: requestedTerms, requested_location_text: requestedLocationText, unmatched_terms: unmatchedTerms,
  zone_status: zoneStatus, zone_candidates: plan.zone_candidates || [], conflict: plan.conflict || null,
  applied: { municipality: plan.municipality || null, zone: plan.zone || null, facets: plan.facets || {}, residue: plan.residue || '' },
} }];

const r = $('Format For Agent').first().json;
let ro={}; try{ ro=$('Plan').first().json||{}; }catch(e){}
if (ro.path === 'empty') return [{ json: r }];

// Clusters comerciales de Simarro, TODA la Comunidad de Madrid (18-ago-2026, decision Manu:
// "actualiza la lista con todo Madrid"). Base: las 9 comarcas oficiales de la Comunidad de
// Madrid (es.wikipedia.org/wiki/Anexo:Municipios_y_comarcas_de_la_Comunidad_de_Madrid,
// verificado 179/179 municipios); la comarca "Area Metropolitana y Corredor del Henares" se
// partio en 4 sub-zonas reales (noroeste/henares/sur/norte metropolitano) porque mezclaba
// puntas opuestas de Madrid (ej. Boadilla y Alcala de Henares) bajo una sola etiqueta, inutil
// para "cercania" real de comprador. Un cluster NUNCA se mezcla con otro, y ninguno incluye
// Madrid capital (mercado demasiado distinto/amplio para ser un 'cerca' util). Fuera de estos
// 12 clusters (resto de España, ej. Montuiri/Mallorca), sin cluster: solo coincidencia exacta,
// no se inventan vecinos que no existen en cartera.
// CORREGIDO 18-ago: Villaviciosa de Odón estaba mal en 'sierra' -- pertenece oficialmente al
// area metropolitana noroeste junto a Boadilla, no a la Cuenca del Guadarrama.
const CLUSTERS = [
  { name: 'sierra_norte', towns: ['la acebeda', 'alameda del valle', 'el atazar', 'berzosa del lozoya', 'el berrueco', 'braojos', 'buitrago del lozoya', 'bustarviejo', 'cabanillas de la sierra', 'la cabrera', 'canencia', 'cervera de buitrago', 'garganta de los montes', 'gargantilla del lozoya y pinilla de buitrago', 'gascones', 'la hiruela', 'horcajo de la sierra-aoslos', 'horcajuelo de la sierra', 'lozoya', 'lozoyuela-navas-sieteiglesias', 'madarcos', 'montejo de la sierra', 'navalafuente', 'navarredonda y san mames', 'patones', 'pinilla del valle', 'pinuecar-gandullas', 'pradena del rincon', 'puebla de la sierra', 'puentes viejas', 'rascafria', 'reduena', 'robledillo de la jara', 'robregordo', 'la serna del monte', 'somosierra', 'torrelaguna', 'torremocha de jarama', 'valdemanco', 'el vellon', 'venturada', 'villavieja del lozoya'] },
  { name: 'sierra_oeste', towns: ['aldea del fresno', 'cadalso de los vidrios', 'cenicientos', 'chapineria', 'colmenar del arroyo', 'fresnedillas de la oliva', 'navalagamella', 'navas del rey', 'pelayos de la presa', 'robledo de chavela', 'rozas de puerto real', 'san martin de valdeiglesias', 'santa maria de la alameda', 'valdemaqueda', 'villa del prado', 'villamanta', 'villamantilla', 'villanueva de perales', 'zarzalejo'] },
  { name: 'vegas', towns: ['ambite', 'aranjuez', 'belmonte de tajo', 'brea de tajo', 'carabana', 'chinchon', 'ciempozuelos', 'colmenar de oreja', 'estremera', 'fuentiduena de tajo', 'morata de tajuna', 'orusco de tajuna', 'perales de tajuna', 'san martin de la vega', 'tielmes', 'titulcia', 'valdaracete', 'valdelaguna', 'valdilecha', 'villaconejos', 'villamanrique de tajo', 'villar del olmo', 'villarejo de salvanes'] },
  { name: 'cuenca_guadarrama', towns: ['alpedrete', 'becerril de la sierra', 'el boalo', 'brunete', 'cercedilla', 'collado mediano', 'collado villalba', 'colmenarejo', 'el escorial', 'galapagar', 'guadarrama', 'los molinos', 'moralzarzal', 'navacerrada', 'quijorna', 'san lorenzo de el escorial', 'valdemorillo', 'villanueva de la canada', 'villanueva del pardillo'] },
  { name: 'cuenca_alta_manzanares', towns: ['colmenar viejo', 'guadalix de la sierra', 'hoyo de manzanares', 'manzanares el real', 'miraflores de la sierra', 'soto del real'] },
  { name: 'campina_henares', towns: ['anchuelo', 'campo real', 'corpa', 'loeches', 'nuevo baztan', 'olmeda de las fuentes', 'pezuela de las torres', 'pozuelo del rey', 'santorcaz', 'los santos de la humosa', 'torres de la alameda', 'valverde de alcala', 'villalbilla'] },
  { name: 'cuenca_media_jarama', towns: ['ajalvir', 'algete', 'camarma de esteruelas', 'cobena', 'daganzo de arriba', 'fresno de torote', 'fuente el saz de jarama', 'meco', 'el molar', 'paracuellos de jarama', 'pedrezuela', 'ribatejada', 'san agustin del guadalix', 'talamanca de jarama', 'valdeavero', 'valdeolmos-alalpardo', 'valdepielagos', 'valdetorres de jarama'] },
  { name: 'sur', towns: ['el alamo', 'arroyomolinos', 'batres', 'casarrubuelos', 'cubas de la sagra', 'grinon', 'humanes de madrid', 'moraleja de enmedio', 'navalcarnero', 'serranillos del valle', 'sevilla la nueva', 'torrejon de la calzada', 'torrejon de velasco', 'valdemoro'] },
  { name: 'noroeste_metropolitano', towns: ['boadilla del monte', 'majadahonda', 'las rozas de madrid', 'pozuelo de alarcon', 'torrelodones', 'villaviciosa de odon'] },
  { name: 'corredor_henares', towns: ['alcala de henares', 'coslada', 'san fernando de henares', 'torrejon de ardoz', 'mejorada del campo', 'velilla de san antonio', 'rivas-vaciamadrid', 'arganda del rey'] },
  { name: 'sur_metropolitano', towns: ['alcorcon', 'fuenlabrada', 'getafe', 'leganes', 'mostoles', 'parla', 'pinto'] },
  { name: 'norte_metropolitano', towns: ['alcobendas', 'san sebastian de los reyes', 'tres cantos'] },
];
const norm=s=>(s||'').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();

const asked=ro.address_contains||ro.municipality||null;
const askedNorm = norm(asked);
const cluster = asked ? CLUSTERS.find(c => c.towns.includes(askedNorm)) : null;
const clusterTowns = cluster ? new Set(cluster.towns) : null;
const anyClusterTown = new Set(CLUSTERS.flatMap(c => c.towns)); // fallback: busqueda generica sin zona

let cat=[]; try{ cat=$('Get Catálogo').all().map(i=>i.json).filter(x=>x&&!Array.isArray(x)&&x.municipality); }catch(e){ cat=[]; }
const maxP=ro.max_price||null,minP=ro.min_price||null,minR=ro.min_rooms||null,minS=ro.min_size||null,resi=!!ro.applyResiFilter;
const counts={};
for(const p of cat){ const m=p.municipality;
  if(asked&&norm(m)===askedNorm)continue;
  if(resi&&p.address&&/^(local|garaje|trastero|terreno|nave|parcela|edificio)\b/i.test(p.address))continue;
  if(maxP&&p.price!=null&&Number(p.price)>maxP)continue;
  if(minP&&p.price!=null&&Number(p.price)<minP)continue;
  if(minR&&p.rooms!=null&&Number(p.rooms)<minR)continue;
  if(minS&&p.size_m2!=null&&Number(p.size_m2)<minS)continue;
  if (asked) {
    if (!clusterTowns) continue; // la zona pedida no pertenece a ningun cluster conocido -> sin 'cerca'
    if (!clusterTowns.has(norm(m))) continue; // solo el MISMO cluster, nunca mezclar nucleo/sierra
  } else {
    if (!anyClusterTown.has(norm(m))) continue; // busqueda generica: cualquier zona comercial conocida
  }
  counts[m]=(counts[m]||0)+1; }
const zones=Object.entries(counts).map(([municipio,count])=>({municipio,count})).sort((a,b)=>b.count-a.count);
const zt=zones.map(z=>z.municipio).join(', ');

// Fuera de zona (18-ago, decision Manu): si lo pedido ni siquiera aparece en la cartera actual
// (ej. "Alcala de Henares", "Benidorm") -- ni coincidencia exacta ni cluster -- avisar de que
// Simarro no opera ahi, en vez del generico "no tengo con esos criterios, ¿ampliamos?" que da a
// entender que quizas SI haya algo si se insiste. Coincidencia por substring en ambos sentidos
// contra TODA la cartera activa (sin filtrar por precio/habitaciones: es presencia geografica,
// no disponibilidad concreta).
let message;
if (zones.length) {
  message = 'No hay nada en esa zona con esos criterios. Donde si hay viviendas que encajan ahora mismo, cerca: ' + zt + '.';
} else if (asked) {
  const enCartera = cat.some(p => { const m = norm(p.municipality); return askedNorm.includes(m) || m.includes(askedNorm); });
  message = enCartera
    ? r.message
    : 'No trabajamos en esa zona -- nuestra cartera está centrada en el noroeste de Madrid (Majadahonda, Las Rozas, Pozuelo, Boadilla del Monte y alrededores). ¿Buscas por esa zona o prefieres que te cuente qué tenemos disponible?';
} else {
  message = r.message;
}
return [{ json: { ...r, message, zones } }];

// Persiste en Kommo las preferencias de busqueda (zona/precio/habitaciones) que el AI Agent
// ya extrajo de la conversacion para esta llamada a Buscar_viviendas. Alimenta lead_preferences
// (via Reconcile lead_preferences) para que el matching semanal y match_pairs vean estos datos
// desde la primera busqueda, no solo si alguien los rellena a mano en Kommo despues.
//
// Solo WhatsApp pasa Lead_id (lo trae el webhook del chatbot) -> en voz shouldPatch sale
// siempre false y el siguiente IF va directo a Return busqueda sin tocar Kommo (en voz las
// preferencias las captura por su lado Captura_interes_llamadas_voz tras colgar).
// Nunca pisa con vacio: solo manda los campos que vienen rellenos esta vez.
//
// IMPORTANTE: este nodo SIEMPRE devuelve 1 item (nunca []). Un array vacio corta el flujo
// aqui mismo y Return busqueda no llegaria a ejecutarse (n8n no propaga con 0 items).
//
// Leemos del nodo Start explicitamente: a esta altura $json es lo que dejo Format For Agent
// (found/message/results), no los argumentos originales de la busqueda.
const start = $('Start').item.json;
const leadId = start.Lead_id;

const municipality = (start.municipality || '').toString().trim();
const maxPrice = Number(start.max_price) || null;
const minPrice = Number(start.min_price) || null;
const minRooms = Number(start.min_rooms) || null;

const cf = [];
if (municipality) cf.push({ field_id: 1373285, values: [{ value: municipality } ] });
if (maxPrice)     cf.push({ field_id: 1376040, values: [{ value: maxPrice } ] });
if (minPrice)     cf.push({ field_id: 1376044, values: [{ value: minPrice } ] });
// CF 1373289 (Habitaciones) es un select de Kommo con opciones fijas '1'..'4','5+'.
// Mandar un numero libre (p.ej. 2) hace que Kommo rechace el PATCH ENTERO -> se perdian
// tambien zona y precio, que si eran validos. Se normaliza a la opcion mas cercana.
let habOption = null;
if (minRooms) habOption = minRooms >= 5 ? '5+' : String(Math.max(1, Math.round(minRooms)));
if (habOption) cf.push({ field_id: 1373289, values: [{ value: habOption } ] });

const shouldPatch = Boolean(leadId) && cf.length > 0;

return [{ json: { shouldPatch, lead_id: leadId || null, custom_fields_values: cf } }];

// Plan v3 — nodo Code "Plan" (runOnceForAllItems), justo despues del HTTP "Resolve Zones"
// (POST /rest/v1/rpc/resolve_zones_json, body {"p_inputs": $json.resolve_inputs}).
// Recibe los CANDIDATOS de lugar que Postgres encontro en el texto y decide cuales aplicar:
//   - municipio (eje "donde", nivel 1) y una sub-zona (distrito/barrio/calle/provincia, nivel 2)
//   - conflicto municipio vs sub-zona: gana la mas especifica (bug 5-sep: "Las Rozas" + "Satelites")
//   - ambiguedad ('centro' existe en Madrid y en Villaviciosa): NO se aplica; se devuelve la lista
//     para que el agente pregunte, y el resto de la consulta sigue como descriptiva
//   - lo que el LLM declaro como lugar y no existe en la cartera -> 'unresolved' (=> partial)
// Salida: rpc_args para search_properties_json + flags para Format For Agent + los campos que
// Build Zones leia del Router (municipality, address_contains, max_price...).
const router = $('Router').first().json;
const cands = (($json && $json.candidates) || []).map(c => ({ ...c, score: Number(c.score) || 0 }));

const SPEC = { street: 5, neighborhood: 4, district: 3, municipality: 2, province: 1 };
const STOP = new Set(['en','de','del','la','el','los','las','un','una','unos','unas','al','y','o','con','sin','por','para','que','me','mi','es','esta','este','sobre','algo','nada','busco','quiero','hay','tiene','tengo','zona','barrio','calle','avenida','avda','paseo','plaza','camino','carretera','urbanizacion','urb','colonia','distrito','municipio','pueblo','cerca','junto','hacia','residencial','parque']);
const norm = s => (s == null ? '' : String(s)).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const rank = (a, b) => (b.exact - a.exact) || (b.tok_len - a.tok_len) || (b.score - a.score) || ((SPEC[b.kind] || 0) - (SPEC[a.kind] || 0));
const isMuniLevel = c => c.kind === 'municipality' || c.kind === 'province';
const coreLen = c => String(c.ngram || '').split(' ').filter(t => !STOP.has(t)).length; // palabras que de verdad se compararon

let muni = null;          // { name, kind:'municipality'|'province' }
let zone = null;          // { kind, name, municipality }
let zoneStatus = 'none';  // applied | unresolved | ambiguous | none
let conflict = null;
let zoneCandidates = [];
let requestedLocationText = '';
const consumed = new Set(); // posiciones de la query consumidas por zonas

const sameMuni = (c, m) => !m || !c.municipality || norm(c.municipality) === norm(m.name) || norm(c.municipality).startsWith(norm(m.name) + ' ');

// 1. municipality (el LLM lo declaro): puede venir un municipio, un ASR de municipio o, mal
//    usado, un distrito ("Los Satelites"). Se toma lo mejor; si es sub-zona, pasa a zone.
{
  const list = cands.filter(c => c.src === 'municipality').sort(rank);
  const best = list[0];
  if (best && isMuniLevel(best)) muni = { name: best.name, kind: best.kind };
  else if (best) { zone = { kind: best.kind, name: best.name, municipality: best.municipality }; zoneStatus = 'applied'; muni = best.municipality ? { name: best.municipality, kind: 'municipality' } : null; }
  else if (router.municipality) muni = { name: router.municipality, kind: 'raw' }; // prefijo en el RPC
}

// 2. address_contains (declarado como lugar): preferir lo que este dentro del municipio.
if (router.address_contains) {
  const list = cands.filter(c => c.src === 'address').sort(rank);
  const inside = list.filter(c => sameMuni(c, muni));
  const best = (inside.length ? inside : list)[0];
  if (!best) { zoneStatus = 'unresolved'; requestedLocationText = router.address_contains; }
  else if (isMuniLevel(best)) { if (!muni || muni.kind === 'raw') muni = { name: best.name, kind: best.kind }; else if (norm(best.name) !== norm(muni.name)) { conflict = `address ${best.name} vs municipality ${muni.name}`; muni = { name: best.name, kind: best.kind }; } }
  else {
    if (muni && !sameMuni(best, muni)) { conflict = `zone ${best.name} (${best.municipality}) vs municipality ${muni.name}`; muni = { name: best.municipality, kind: 'municipality' }; }
    zone = { kind: best.kind, name: best.name, municipality: best.municipality }; zoneStatus = 'applied';
    requestedLocationText = router.address_contains;
  }
}

// 3. query libre: greedy sobre spans no solapados, del mas largo/exacto al mas corto.
{
  const list = cands.filter(c => c.src === 'query').sort(rank);
  const taken = [];
  for (const c of list) {
    const overlaps = taken.some(t => c.tok_start < t.tok_start + t.tok_len && t.tok_start < c.tok_start + c.tok_len);
    if (overlaps) continue;
    // Fuzzy de UNA palabra (contando el core, como hace resolve_zones desde 002: 'urbanizacion
    // monte' o 'el cano' son una palabra) cuya frase continua con algo que no es lugar ni
    // stopword: era el principio de un nombre mas largo que NO existe ('urbanizacion Monte
    // Alegre' -> 'monte'). 'el cano' (next_tok null) o 'el centro de' (next_tok stopword) pasan.
    if (!c.exact && coreLen(c) <= 1 && c.next_tok && !STOP.has(c.next_tok)) {
      const nextCovered = taken.some(t => c.tok_start + 1 >= t.tok_start && c.tok_start + 1 < t.tok_start + t.tok_len);
      if (!nextCovered) continue;
    }
    if (isMuniLevel(c)) {
      if (!muni || muni.kind === 'raw') muni = { name: c.name, kind: c.kind };
      taken.push(c); continue;
    }
    if (zone) { taken.push(c); continue; } // ya hay sub-zona (la mas especifica/larga gano antes)
    // Todos los candidatos de este mismo span (cualquier certeza)
    const span = list.filter(o => o.tok_start === c.tok_start && o.tok_len === c.tok_len && !isMuniLevel(o)).sort(rank);
    const insideMuni = muni ? span.filter(o => sameMuni(o, muni)) : [];
    if (muni && insideMuni.length) {
      // dentro del municipio pedido gana aunque sea fuzzy: 'centro' + Las Rozas -> 'Rozas Centro'
      zone = { kind: insideMuni[0].kind, name: insideMuni[0].name, municipality: insideMuni[0].municipality }; zoneStatus = 'applied';
    } else {
      // sin municipio (o fuera de el): solo el grupo de maxima certeza cuenta para decidir
      const top = span.filter(o => o.exact === c.exact && Math.abs(o.score - c.score) < 1e-6);
      const munis = [...new Set(top.map(o => norm(o.municipality || o.name)))];
      if (munis.length > 1) {
        if (zoneStatus === 'none') { zoneStatus = 'ambiguous'; zoneCandidates = top.map(o => ({ kind: o.kind, name: o.name, municipality: o.municipality })); requestedLocationText = c.ngram; }
      } else {
        if (muni) conflict = `zone ${c.name} (${c.municipality}) vs municipality ${muni.name}`;
        zone = { kind: c.kind, name: c.name, municipality: c.municipality }; zoneStatus = 'applied';
        if (c.municipality) muni = { name: c.municipality, kind: 'municipality' };
      }
    }
    if (!requestedLocationText) requestedLocationText = c.ngram;
    taken.push(c);
  }
  for (const t of taken) for (let i = 0; i < t.tok_len; i++) consumed.add(t.tok_start + i);
}

// 3a. Ambiguedad ('centro' existe en Madrid y en Villaviciosa) con municipio conocido, venga del
// LLM o de la propia query en cualquier orden ('el centro de Majadahonda' resuelve 'centro' antes
// que 'majadahonda'): si un candidato esta en ese municipio, es ese; si ninguno lo esta, la zona
// pedida NO tiene stock ahi -> 'unresolved' (=> partial). Antes quedaba 'ambiguous' y Format lo
// etiquetaba 'exact' con viviendas de otra parte del municipio (el CRM las anclaba como la pedida).
if (zoneStatus === 'ambiguous' && muni) {
  const inside = zoneCandidates.filter(o => sameMuni(o, muni));
  zoneCandidates = [];
  if (inside.length) { zone = { kind: inside[0].kind, name: inside[0].name, municipality: inside[0].municipality }; zoneStatus = 'applied'; if (inside[0].municipality) muni = { name: inside[0].municipality, kind: 'municipality' }; }
  else zoneStatus = 'unresolved';
}

// 3b. El cliente nombro un sitio que NO existe en la cartera -> 'unresolved' (=> partial, texto
// honesto: 'En la chopera no me sale nada'). Es la causa comun de 'La Chopera' y 'zona norte de
// Madrid' marcados exact: el residuo de la query se trataba siempre como descriptor ('luminoso').
// Senales de que un token no resuelto es un LUGAR y no un descriptor:
//   (a) marcador fuerte delante: calle/urbanizacion/barrio/zona... ('urbanizacion Monte Alegre', 'zona norte')
//   (b) articulo delante: el/la/los/las                             ('La Chopera', 'en la sierra')
//   (c) nombre propio: el LLM lo escribio con mayuscula inicial     ('piso en Chopera'; no la 1a palabra)
// 'en'/'cerca'/'por' solos son demasiado genericos ('en buen estado', 'cerca de colegios').
if (!zone && zoneStatus !== 'ambiguous' && zoneStatus !== 'unresolved') {
  const qt = (router.zone_text || '').split(' ').filter(Boolean);
  const STRONG = new Set(['calle','avenida','avda','paseo','plaza','camino','carretera','urbanizacion','urb','barrio','colonia','residencial','zona']);
  const ART = new Set(['el','la','los','las']);
  const proper = new Set();
  String(router.query || '').split(/\s+/).filter(Boolean).forEach((w, k) => { if (k > 0 && /^[A-ZÁÉÍÓÚÑ][a-záéíóúñ]/.test(w)) proper.add(norm(w)); });
  const free = i => i < qt.length && !consumed.has(i) && !STOP.has(qt[i]) && !/^\d+$/.test(qt[i]);
  let start = -1, label = -1;
  for (let i = 0; i < qt.length && start < 0; i++) {
    if (!free(i)) continue;
    const prev = i > 0 ? qt[i - 1] : '';
    if (STRONG.has(prev) || ART.has(prev)) { start = i; label = i - 1; }
    else if (proper.has(qt[i])) { start = i; label = i; }
  }
  if (start >= 0) {
    let end = start; while (end < start + 4 && free(end)) end++;
    zoneStatus = 'unresolved'; requestedLocationText = qt.slice(label, end).join(' ');
    for (let i = start; i < end; i++) consumed.add(i);
  }
}

// 4. Residuo descriptivo = tokens de la query que no son facetas, ni zona, ni stopwords.
const qTokens = (router.zone_text || '').split(' ').filter(Boolean);
const residue = qTokens.filter((t, i) => !consumed.has(i) && !STOP.has(t) && !/^\d+$/.test(t));
const USE_EMBEDDING = true; // fase 1b: ranking semantico solo cuando queda residuo descriptivo
const needsEmbedding = USE_EMBEDDING && (router.path === 'search' || router.path === 'browse') && residue.length > 0;

const f = router.facets || {};
// Una provincia ("Mallorca" -> Balears) no es municipio: viaja como zona de nivel provincia.
if (muni && muni.kind === 'province') { if (!zone) zone = { kind: 'province', name: muni.name, municipality: null }; if (zoneStatus === 'none') zoneStatus = 'applied'; muni = null; }
const rpcArgs = {
  p_idealista_id: router.derivedId || null,
  p_municipality: muni ? muni.name : null,
  p_zone_kind: zone ? zone.kind : null,
  p_zone_name: zone ? zone.name : null,
  p_types: (f.types && f.types.length) ? f.types : null,
  p_features: (f.features && f.features.length) ? f.features : null,
  p_condition: f.condition || null,
  p_min_rooms: router.min_rooms || null,
  p_min_size: router.min_size || null,
  p_min_price: router.min_price || null,
  p_max_price: router.max_price || null,
  p_include_non_residential: !router.applyResiFilter,
  p_exclude_ids: router.exclude_ids || [],
  p_limit: router.path === 'byId' ? 1 : Math.max(router.match_count || 5, (router.path === 'browse' || (!muni && !zone && !f.types?.length && !f.features?.length && !router.min_rooms && !router.max_price && !router.min_price && !router.min_size)) ? 25 : 0),
};

return [{ json: {
  // compat Build Zones / Preparar CF (leian estos nombres del Router)
  path: router.path, applyResiFilter: router.applyResiFilter, query: router.query,
  municipality: muni ? muni.name : null, address_contains: zone ? zone.name : (router.address_contains || null),
  max_price: router.max_price, min_price: router.min_price, min_rooms: router.min_rooms, min_size: router.min_size,
  match_count: router.match_count, exclude_ids: router.exclude_ids,
  // decision
  rpc_args: rpcArgs,
  zone_status: zoneStatus, zone, muni, conflict, zone_candidates: zoneCandidates,
  requested_location_text: requestedLocationText,
  facets: f, residue: residue.join(' '), needs_embedding: needsEmbedding,
}}];
